import { FunctionalComponent,RefObject } from 'preact';
import { useSelector } from 'react-redux';

import { selectActiveView, selectUi } from '../../../slice';

import { getTranslation } from '../../../../../../shared/chromeApi';
import CategoryView from './components/CategoryView';
import CustomizeOptions from './components/CustomizeOptions';
import CustomizePopupNav from './components/CustomizePopupNav';
import DragAndDrop from './components/DragAndDrop';

import ArrowBackIcon from '@material-ui/icons/ArrowBack';
import BellIcon from '@material-ui/icons/NotificationsNone';
import CloseIcon from '@material-ui/icons/Cancel';

import styles from './styles.module.scss';

interface CustomizePopupProps {
  onClose: () => void;
  goBack: () => void;
}

const CustomizePopup: FunctionalComponent<CustomizePopupProps> = ({
  onClose,
  goBack,
}: CustomizePopupProps) => {
  const { customPicture } = useSelector(selectUi);

  const { view } = useSelector(selectActiveView);

  const Component = {
    default: CustomizeOptions,
    dark: CustomizeOptions,
    custom: DragAndDrop,
    gallery: CategoryView,
  }[view];

  const showWarning = (): string | null => {
    if (view === 'gallery') {
      return 'avoid_bg_pictures';
    } else if (view === 'custom' && customPicture.warning) {
      return customPicture.warning;
    }

    return null;
  };

  return (
    <div className={styles.customizePopup}>
      <div className={styles.customizePopupHeader}>
        <h3 className={styles.title}>
          {getTranslation('background_popup_title')}
        </h3>
        {(view === 'custom' || view === 'gallery') && (
          <button className={styles.back} onClick={goBack}>
            <ArrowBackIcon fontSize="small" className={styles.backIcon} />
          </button>
        )}
        {showWarning() && (
          <div className={styles.slowWarn}>
            <BellIcon className={styles.bellIcon} />
            {getTranslation(showWarning())}
          </div>
        )}
        <button className={styles.close} onClick={onClose}>
          <CloseIcon fontSize="small" className={styles.closeIcon} />
        </button>
      </div>
      <div className={styles.customizePopupContent}>
        <CustomizePopupNav />
        <Component />
      </div>
    </div>
  );
};

export default CustomizePopup;
