import { FunctionalComponent } from 'preact';
import { useState, useEffect } from 'preact/hooks';
import { useDispatch, useSelector } from 'react-redux';
import cn from 'classnames';

import { LazyLoadImage } from 'react-lazy-load-image-component';

import { getTranslation } from '../../../../../../../../shared/chromeApi';
import { Picture, Rotation, Video } from '../../../../../slice/types';
import { thumbnails } from '../../shared';
import { Sync } from '@material-ui/icons';

import {
  fetchVideos,
  selectActiveView,
  selectUi,
  selectedCollection,
  updateVideo,
} from '../../../../../slice';
import {
  getResolutionUrl,
  preloadPicture,
  preloadVideo,
} from '../../../../../slice/utils';
import { fetchBackgrounds } from '../../../../../slice';

import styles from './styles.module.scss';

const CategoryView: FunctionalComponent = () => {
  const dispatch = useDispatch();

  const [backgrounds, setBackgrounds] = useState(null);
  const [videos, setVideos] = useState(null);

  useEffect(() => {
    fetchBackgrounds().then(setBackgrounds);
    fetchVideos().then(setVideos);
  }, []);

  const {
    mode,
    gallery: { category, rotation, image },
    videoBackground,
  } = useSelector(selectUi);
  const { category: activeCategory } = useSelector(selectActiveView);

  const [{ show, content, position }, setPopoverState] = useState({
    show: false,
    content: null,
    position: '',
  });

  const selectBackgroundImage = async (picture: Picture, rotation?) => {
    console.log(picture, rotation);

    if (!rotation) {
      await preloadPicture(
        getResolutionUrl(
          window.screen.width,
          backgrounds.resolutions,
          picture.url
        )
      );
    }

    dispatch(
      selectedCollection({
        rotation,
        category: activeCategory,
        now: Date.now(),
        ...(picture && {
          picture: {
            ...picture,
            originUrl: picture.url,
            url: getResolutionUrl(
              window.screen.width,
              backgrounds.resolutions,
              picture.url
            ),
          },
        }),
      })
    );

    dispatch(updateVideo({ show: false }));
  };

  const setBackgroundVideo = async (
    video: Video,
    index = 0,
    rotation: Rotation = null
  ) => {
    if (!video && rotation) {
      dispatch(updateVideo({ rotation }));
      return;
    }

    await preloadVideo(
      `https://assets.oceanhero.today/backgrounds/videos/${video.url}`
    ); // `https://assets.oceanhero.today/backgrounds/videos/${video.url}

    dispatch(
      updateVideo({
        show: true,
        url: `https://assets.oceanhero.today/backgrounds/videos/${video.url}`,
        title: 'Video by ' + video.user.name,
        credit: { title: 'From Pexels', url: video.url },
        id: video.id,
        rotation,
        index,
        viewCount: 1,
      })
    );
  };

  const onRotationClick = (type: string, value: number | null): void => {
    if (activeCategory !== 'video') {
      selectBackgroundImage(
        category === activeCategory
          ? null
          : backgrounds.categories[activeCategory][0],
        {
          type,
          value,
          category: activeCategory,
        }
      );
    } else {
      setBackgroundVideo(videoBackground.show ? null : videos[0], 0, {
        type,
        value,
        category: activeCategory,
      });
    }
  };

  const handlePopover = (
    content: string | null,
    position: string | null
  ): void => {
    setPopoverState(({ show }) => ({ show: !show, content, position }));
  };

  if (!backgrounds) return null;

  const rotationOptions = [
    {
      onShowPopover: (): void => handlePopover('2 tabs', 'first'),
      onClick: (): void => onRotationClick('byTabs', 2),
      isActive:
        mode === 'gallery' &&
        rotation.type === 'byTabs' &&
        rotation.value === 2 &&
        ((activeCategory === category && !videoBackground?.show) ||
          (activeCategory === 'video' && videoBackground?.show)),
      optionTranslation: 'category_every_2_tabs',
    },
    {
      onShowPopover: (): void => handlePopover('5 tabs', 'second'),
      onClick: (): void => onRotationClick('byTabs', 5),
      isActive:
        mode === 'gallery' &&
        rotation.type === 'byTabs' &&
        rotation.value === 5 &&
        ((activeCategory === category && !videoBackground?.show) ||
          (activeCategory === 'video' && videoBackground?.show)),
      optionTranslation: 'category_every_5_tabs',
    },
    {
      onShowPopover: (): void => handlePopover('day', 'third'),
      onClick: (): void => onRotationClick('byDays', null),
      isActive:
        mode === 'gallery' &&
        rotation.type === 'byDays' &&
        ((activeCategory === category && !videoBackground?.show) ||
          (activeCategory === 'video' && videoBackground?.show)),
      optionTranslation: 'category_every_day',
    },
  ];

  const rotationOptionsVideos = [
    {
      onShowPopover: (): void => handlePopover('5 tabs', 'first'),
      onClick: (): void => onRotationClick('byTabs', 5),
      isActive:
        mode === 'gallery' &&
        rotation.type === 'byTabs' &&
        rotation.value === 5 &&
        ((activeCategory === category && !videoBackground?.show) ||
          (activeCategory === 'video' && videoBackground?.show)),
      optionTranslation: 'category_every_5_tabs',
    },
    {
      onShowPopover: (): void => handlePopover('10 tabs', 'second'),
      onClick: (): void => onRotationClick('byTabs', 10),
      isActive:
        mode === 'gallery' &&
        rotation.type === 'byTabs' &&
        rotation.value === 10 &&
        ((activeCategory === category && !videoBackground?.show) ||
          (activeCategory === 'video' && videoBackground?.show)),
      optionTranslation: 'category_every_10_tabs',
    },
    {
      onShowPopover: (): void => handlePopover('day', 'third'),
      onClick: (): void => onRotationClick('byDays', null),
      isActive:
        mode === 'gallery' &&
        rotation.type === 'byDays' &&
        ((activeCategory === category && !videoBackground?.show) ||
          (activeCategory === 'video' && videoBackground?.show)),
      optionTranslation: 'category_every_day',
    },
  ];

  return (
    <div className={styles.categoryOptions}>
      {show && (
        <div className={`${styles.rotationPopover} ${styles[position]}`}>
          {activeCategory === 'video'
            ? getTranslation('rotation_popover_1_video')
            : getTranslation('rotation_popover_1')}{' '}
          {content}{' '}
          {activeCategory === 'video'
            ? getTranslation('rotation_popover_2_video')
            : getTranslation('rotation_popover_2')}
        </div>
      )}

      <div className={styles.rotationOptionTitle}>
        <Sync />
        <span>
          {' '}
          {activeCategory === 'video'
            ? getTranslation('category_show_new_video')
            : getTranslation('category_show_new_picture')}
        </span>
      </div>

      <div className={styles.rotationOptions}>
        {(activeCategory !== 'video'
          ? rotationOptions
          : rotationOptionsVideos
        ).map(({ optionTranslation, onShowPopover, onClick, isActive }) => (
          <button
            key={optionTranslation}
            onMouseEnter={onShowPopover}
            onMouseLeave={(): void => handlePopover(null, '')}
            onClick={onClick}
            className={`${styles.customizeOption} ${
              isActive ? styles.activeRotation : ''
            }`}
          >
            <div
              className={`${styles.optionPreview} ${styles.noBorder}`}
              style={`background-image: linear-gradient(rgba(0, 0, 0, 0.5), rgba(0, 0, 0, 0.5)), url(${
                activeCategory === 'video'
                  ? 'https://assets.oceanhero.today/backgrounds/videos/856882.jpeg'
                  : thumbnails[activeCategory]
              })`}
            />
            <div className={styles.backdrop}></div>
            <span className={styles.optionTitle}>
              {/* <strong>
                  {activeCategory === 'video'
                    ? getTranslation('category_show_new_video')
                    : getTranslation('category_show_new_picture')}
                </strong> */}
              {getTranslation('category_every_capitalized')}{' '}
              {getTranslation(optionTranslation)}
            </span>
          </button>
        ))}
      </div>

      {activeCategory !== 'video' &&
        backgrounds.categories[activeCategory]?.map((item: Picture) => (
          <button
            key={item.url}
            onClick={() => selectBackgroundImage(item)}
            className={cn(
              styles.customizeOption,
              !rotation.type &&
                activeCategory === category &&
                item.url === image.picture.originUrl
                ? styles.activeRotation
                : ''
            )}
          >
            <LazyLoadImage
              className={`${styles.optionPreview} ${styles.noBorder}`}
              src={getResolutionUrl(220, backgrounds.resolutions, item.url)}
            />
          </button>
        ))}

      {activeCategory === 'video' &&
        videos &&
        videos?.map((item: Video, i) => (
          <button
            key={item.url}
            onClick={() => setBackgroundVideo(item, i)}
            className={cn(
              styles.customizeOption,
              !rotation.type &&
                videoBackground?.show &&
                item?.id === videoBackground?.id
                ? styles.activeRotation
                : ''
            )}
          >
            <LazyLoadImage
              className={`${styles.optionPreview} ${styles.noBorder}`}
              src={`https://assets.oceanhero.today/backgrounds/videos/${item.image}`}
            />
          </button>
        ))}
    </div>
  );
};

export default CategoryView;
